function pickBodyAttachment(){const input=$('bodyScanPicker');if(!input)return;input.value='';input.onchange=()=>{const f=input.files?.[0];if(!f)return;if(f.size>12*1024*1024)return toast('첨부 파일은 12MB 이하를 권장합니다.');bodyAttachmentDraft={file:f,name:f.name,type:f.type};const n=$('bodyAttachmentName');if(n)n.textContent=f.name;toast('인바디 파일을 저장 준비했습니다.');};input.click();}
