function latestWorkoutSessionSummary(){const last=state.workouts.at(-1);if(!last)return null;const items=last.sessionId?state.workouts.filter(x=>x.sessionId===last.sessionId):[last],top=items.slice().sort((a,b)=>(num(b.estimated1RM)||calcEstimated1RM(b.weight,b.reps))-(num(a.estimated1RM)||calcEstimated1RM(a.weight,a.reps)))[0];return {kind:'workout',date:last.date||today(),name:items.length>1?`${muscleLabelFromKey(exerciseMuscle(top?.name).key)} SESSION`:last.name,duration:sum(items,x=>num(x.duration)),volume:sum(items,x=>num(x.volume)),kcal:sum(items,x=>num(x.kcal)),topLift:top?`${top.name} · ${shownWeight(top.weight,1)}${weightUnit()} × ${top.reps}`:'—',sets:sum(items,x=>num(x.sets)),reps:sum(items,x=>num(x.sets)*num(x.reps))};}
function certInfo(record,kind){
  if(kind==='running'){const r=record||{};return {title:'RUN VERIFIED',headline:`${Number(shownDistance(num(r.distance),2)).toFixed(2)} ${distanceUnit().toUpperCase()}`,sub:`${formatRunMinutes(num(r.duration))} · ${paceText(r)} /${distanceUnit().toUpperCase()}`,date:r.date||today(),metrics:[['TIME',formatRunMinutes(num(r.duration))],['CALORIES',`${Math.round(num(r.kcal))} kcal`],['PACE',`${paceText(r)} /${distanceUnit().toUpperCase()}`]],coords:Array.isArray(r.coords)?r.coords:[]};}
  const s=latestWorkoutSessionSummary()||record||{}, muscle=exerciseMuscle((state.workouts.at(-1)||{}).name||'');return {title:'WORKOUT VERIFIED',headline:s.name||'WORKOUT',sub:s.topLift||'',date:s.date||today(),metrics:[['DURATION',`${Math.round(num(s.duration))} min`],['VOLUME',`${Math.round(shownWeight(num(s.volume),0)).toLocaleString()} ${weightUnit()}`],['CALORIES',`${Math.round(num(s.kcal))} kcal`]],muscleKey:muscle.key,muscleLabel:muscle.label};
}
function formatRunMinutes(min){const sec=Math.max(0,Math.round(num(min)*60)),h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${m}:${String(s).padStart(2,'0')}`;}
function paceText(r){const p=num(r?.duration)/(num(r?.distance)||1);if(!Number.isFinite(p)||!num(r?.distance))return '—';const shown=shownPace(p,3),m=Math.floor(shown),s0=Math.round((shown-m)*60),s=s0===60?0:s0,mm=s0===60?m+1:m;return `${mm}'${String(s).padStart(2,'0')}\"`;}
function routeSignatureSvg(coords=[]){let pts='20,100 35,82 28,67 52,48 44,31 72,23 88,8';if(coords.length>1){const lats=coords.map(p=>p[0]),lons=coords.map(p=>p[1]),minLat=Math.min(...lats),maxLat=Math.max(...lats),minLon=Math.min(...lons),maxLon=Math.max(...lons),dLat=maxLat-minLat||1e-6,dLon=maxLon-minLon||1e-6;pts=coords.slice(-200).map(p=>`${12+76*(p[1]-minLon)/dLon},${104-96*(p[0]-minLat)/dLat}`).join(' ');}return `<svg class="cert-route-signature" viewBox="0 0 100 112" aria-hidden="true"><polyline points="${pts}"/></svg>`;}
function showCert(id,m,record,kind){const area=$(id);if(!area)return;const isVideo=m.type.startsWith('video'),info=certInfo(record,kind);const visual=kind==='running'?routeSignatureSvg(info.coords):`<div class="cert-anatomy" data-muscle="${info.muscleKey||'full'}">${miniBodySvg(info.muscleKey||'full')}</div>`;area.className='cert premium-cert';area.innerHTML=`<div class="cert-media"><${isVideo?'video':'img'} src="${m.url}" ${isVideo?'controls muted playsinline':''} alt="GARANG 인증 미디어"><div class="cert-overlay-signature"><div class="cert-topline"><div class="cert-wordmark">GARANG<small>Know · Understand · Guide · Act</small></div><div class="cert-verified">${info.title}</div></div><div class="cert-vertical-mark"><i></i><b>가<br>랑</b><i></i></div><div class="cert-lower"><div class="cert-main-copy"><strong>${esc(info.headline)}</strong><span>${kind==='running'?'RUNNING SESSION':esc(info.muscleLabel||'PERFORMANCE SESSION')}</span></div>${visual}<div class="cert-metric-line">${info.metrics.map(x=>`<span><i>${x[0]}</i><b>${esc(x[1])}</b></span>`).join('')}</div>${info.sub?`<div class="cert-toplift"><span>${kind==='running'?'SESSION':'TOP LIFT'}</span><b>${esc(info.sub)}</b></div>`:''}<div class="cert-foot"><span>${esc(info.date)} · GARANG</span><em>Garang</em></div></div></div></div><div class="cert-controls">${isVideo?'<button class="ghost small" id="certShare">원본 영상 공유</button><div class="cert-video-note">영상 합성은 서버/네이티브 인코더 연결 전까지 원본을 변조하지 않습니다.</div>':'<button class="primary small" id="certShare">프리미엄 인증 이미지 저장 / 공유</button>'}</div>`;$('certShare').onclick=()=>isVideo?shareMedia(m):shareCompositeImage(m,record,kind);}
async function loadImageFromUrl(url){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=url;});}
function drawRoundRect(c,x,y,w,h,r){r=Math.min(r,w/2,h/2);c.beginPath();c.moveTo(x+r,y);c.lineTo(x+w-r,y);c.quadraticCurveTo(x+w,y,x+w,y+r);c.lineTo(x+w,y+h-r);c.quadraticCurveTo(x+w,y+h,x+w-r,y+h);c.lineTo(x+r,y+h);c.quadraticCurveTo(x,y+h,x,y+h-r);c.lineTo(x,y+r);c.quadraticCurveTo(x,y,x+r,y);c.closePath();}
function drawRouteCanvas(c,coords,x,y,w,h){let pts=[];if(coords?.length>1){const lats=coords.map(p=>p[0]),lons=coords.map(p=>p[1]),minLat=Math.min(...lats),maxLat=Math.max(...lats),minLon=Math.min(...lons),maxLon=Math.max(...lons),dLat=maxLat-minLat||1e-6,dLon=maxLon-minLon||1e-6;pts=coords.slice(-220).map(p=>[x+w*(p[1]-minLon)/dLon,y+h-h*(p[0]-minLat)/dLat]);}else pts=[[x,y+h],[x+w*.22,y+h*.72],[x+w*.14,y+h*.52],[x+w*.52,y+h*.38],[x+w*.44,y+h*.18],[x+w*.82,y]];c.strokeStyle='rgba(247,244,238,.96)';c.lineWidth=Math.max(3,w*.025);c.lineCap='round';c.lineJoin='round';c.beginPath();pts.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.stroke();if(pts.length){c.fillStyle='#63b34f';c.beginPath();c.arc(pts[0][0],pts[0][1],Math.max(5,w*.05),0,Math.PI*2);c.fill();c.fillStyle='#d85448';c.beginPath();c.arc(pts.at(-1)[0],pts.at(-1)[1],Math.max(5,w*.05),0,Math.PI*2);c.fill();}}
